///  Terrain raster solve envelope.
public struct TRS: FlatBufferTable, FlatbuffersVectorInitializable, Verifiable {

  static func validateVersion() { FlatBuffersVersion_25_12_19() }
  public var __buffer: ByteBuffer! { return _accessor.bb }
  private var _accessor: Table

  public static var id: String { "$TRS" }
  public static func finish(_ fbb: inout FlatBufferBuilder, end: Offset, prefix: Bool = false) { fbb.finish(offset: end, fileId: TRS.id, addPrefix: prefix) }
  private init(_ t: Table) { _accessor = t }
  public init(_ bb: ByteBuffer, o: Int32) { _accessor = Table(bb: bb, position: o) }

  private struct VT {
    static let REQUEST: VOffset = 4
    static let RESULT: VOffset = 6
  }

  public var REQUEST: TRSRequest? { let o = _accessor.offset(VT.REQUEST); return o == 0 ? nil : TRSRequest(_accessor.bb, o: _accessor.indirect(o + _accessor.position)) }
  public var RESULT: TRSResult? { let o = _accessor.offset(VT.RESULT); return o == 0 ? nil : TRSResult(_accessor.bb, o: _accessor.indirect(o + _accessor.position)) }
  public static func startTRS(_ fbb: inout FlatBufferBuilder) -> UOffset { fbb.startTable(with: 2) }
  public static func add(REQUEST: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: REQUEST, at: VT.REQUEST) }
  public static func add(RESULT: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: RESULT, at: VT.RESULT) }
  public static func endTRS(_ fbb: inout FlatBufferBuilder, start: UOffset) -> Offset { let end = Offset(offset: fbb.endTable(at: start)); return end }
  public static func createTRS(
    _ fbb: inout FlatBufferBuilder,
    REQUESTOffset REQUEST: Offset = Offset(),
    RESULTOffset RESULT: Offset = Offset()
  ) -> Offset {
    let __start = TRS.startTRS(&fbb)
    TRS.add(REQUEST: REQUEST, &fbb)
    TRS.add(RESULT: RESULT, &fbb)
    return TRS.endTRS(&fbb, start: __start)
  }

  public static func verify<T>(_ verifier: inout Verifier, at position: Int, of type: T.Type) throws where T: Verifiable {
    var _v = try verifier.visitTable(at: position)
    try _v.visit(field: VT.REQUEST, fieldName: "REQUEST", required: false, type: ForwardOffset<TRSRequest>.self)
    try _v.visit(field: VT.RESULT, fieldName: "RESULT", required: false, type: ForwardOffset<TRSResult>.self)
    _v.finish()
  }
}
